DROP TABLE IF EXISTS `kia_faq`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kia_faq` (
  `seq_no` int NOT NULL COMMENT '순번',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '카테고리',
  `question` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '질문',
  `answer` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '답변',
  PRIMARY KEY (`seq_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='KIA FAQ';
