DROP TABLE IF EXISTS `sido_oil_price`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sido_oil_price` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '식별자',
  `sido_cd` varchar(10) NOT NULL COMMENT '시도 구분코드 (SIDOCD)',
  `sido_nm` varchar(50) NOT NULL COMMENT '시도명 (SIDONM)',
  `prod_cd` varchar(10) NOT NULL COMMENT '제품구분코드 (PRODCD)',
  `price` decimal(10,2) NOT NULL COMMENT '평균가격 (PRICE)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='시도별 주유소 평균가격';
/*!40101 SET character_set_client = @saved_cs_client */;

